const MOD = 1000000007;

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for countPathsStartingAt(grid, row, col, memo):
//     returns the number of strictly increasing paths that start at
//     the cell `row`,`col` (modulo 10^9 + 7), and saves that answer
//     in `memo` so it never has to be computed again.
const countPathsStartingAt = (grid, row, col, memo) => {
    // Base case
    // Our real base case is handled automatically: when no neighbor is
    // strictly larger than the current cell, the loop below adds nothing
    // and the count stays at 1 (the cell by itself).
    const curPositionString = getPositionString(row, col);
    if (memo.hasOwnProperty(curPositionString)) return memo[curPositionString];

    // Process node
    // Every cell counts as an increasing path of length 1 by itself.
    let numPathsFromCur = 1;

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        if (!isInBounds(grid, newRow, newCol)) continue;

        // Paths must be strictly increasing, so we only step onto larger
        // values. This also means a path can never loop back on itself,
        // which is why we do not need a visited set.
        if (grid[newRow][newCol] <= grid[row][col]) continue;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns the number of increasing
        // paths starting at the larger neighbor. Trust it, do not
        // trace it. Every path from this cell is either the cell alone
        // or a step onto a larger neighbor followed by a path from
        // there, so 1 plus the neighbors' guaranteed counts is exactly
        // this function's contract, kept.
        const numPathsFromNeighbor = countPathsStartingAt(grid, newRow, newCol, memo);
        numPathsFromCur = (numPathsFromCur + numPathsFromNeighbor) % MOD;
    }

    memo[curPositionString] = numPathsFromCur;

    return numPathsFromCur;
};

const countPaths = (grid) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    let totalNumPaths = 0;
    const memo = {};

    // Every cell can be the start of a path, so we sum the counts
    // from every starting cell.
    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            // The recursive leap of faith: trust the contract. This call
            // returns the number of increasing paths starting at this
            // cell. We do not trace inside; we just add it to the running
            // total.
            const numPathsFromCell = countPathsStartingAt(grid, row, col, memo);
            totalNumPaths = (totalNumPaths + numPathsFromCell) % MOD;
        }
    }

    return totalNumPaths;
};

const VISITING = 1;
const VISITED = 2;

const buildGraph = (prerequisites) => {
    const graph = {};

    for (const prerequisite of prerequisites) {
        const [course, requiredCourse] = prerequisite;

        const courseInGraph = graph.hasOwnProperty(course);
        const requiredCourseInGraph = graph.hasOwnProperty(requiredCourse);

        if (!courseInGraph) graph[course] = [];
        if (!requiredCourseInGraph) graph[requiredCourse] = [];

        // This is a directed graph, so the edge only goes one way:
        // from the required course to the course that needs it.
        graph[requiredCourse].push(course);
    }

    return graph;
};

// CONTRACT for hasCycle(graph, course, courseStates):
//     returns true if a cycle can be reached from `course`, and false
//     otherwise. When it returns false, `course` and everything
//     reachable from it is marked VISITED — fully explored,
//     cycle-free.
const hasCycle = (graph, course, courseStates) => {
    // Base cases
    // A VISITING course is still on our current DFS path, so seeing it
    // again means we looped back around: that is a cycle.
    if (courseStates[course] === VISITING) return true;

    // A VISITED course was fully explored earlier and led to no cycle,
    // so we can safely skip it. This is why we need three states instead
    // of a plain visited set: in a directed graph, reaching an already
    // seen node is only a cycle if that node is on our CURRENT path.
    if (courseStates[course] === VISITED) return false;

    // Process node
    courseStates[course] = VISITING;

    // Recurse on neighbors
    const neighbors = graph[course];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns true exactly when a cycle can
        // be reached from `neighbor`. Trust it, do not trace it. If no
        // neighbor leads to a cycle, then no cycle is reachable from
        // `course` either — which is exactly this function's contract,
        // kept.
        if (hasCycle(graph, neighbor, courseStates)) return true;
    }

    courseStates[course] = VISITED;

    return false;
};

const canFinish = (numCourses, prerequisites) => {
    const graph = buildGraph(prerequisites);

    const courseStates = {};

    for (let course = 0; course < numCourses; course++) {
        // Courses with no prerequisites and no dependents are always fine.
        const courseInGraph = graph.hasOwnProperty(course);
        if (!courseInGraph) continue;

        // We can finish every course as long as no cycle exists.
        // The recursive leap of faith: trust the contract. This call
        // returns true exactly when a cycle can be reached from
        // `course`. We do not trace inside; we just return false the
        // moment any cycle is found.
        if (hasCycle(graph, course, courseStates)) return false;
    }

    return true;
};

const RED = 1;
const BLUE = -1;
const UNCOLORED = 0;

// CONTRACT for canColorFrom(graph, node, color, nodeColors):
//     returns true if `node` can take the color `color` and everything
//     reachable from `node` can be colored so neighbors always get
//     opposite colors — filling those colors into `nodeColors` as it
//     goes. Returns false if that is impossible.
const canColorFrom = (graph, node, color, nodeColors) => {
    // Base case
    // If this node already has a color, we just check that it matches the
    // color we wanted to paint it. A mismatch means two neighbors were
    // forced into the same color, so the graph is not bipartite.
    if (nodeColors[node] !== UNCOLORED) return nodeColors[node] === color;

    // Process node
    nodeColors[node] = color;

    // Recurse on neighbors
    // Every neighbor must get the opposite color. Multiplying by -1
    // flips RED to BLUE and BLUE to RED.
    const oppositeColor = color * -1;

    const neighbors = graph[node];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns true exactly when the
        // neighbor (and everything past it) can be colored with the
        // opposite color. Trust it, do not trace it. This function
        // already colored `node`, and each neighbor's contract covers
        // the rest — together, that is this function's full contract,
        // kept.
        if (!canColorFrom(graph, neighbor, oppositeColor, nodeColors)) return false;
    }

    return true;
};

const isBipartite = (graph) => {
    const numNodes = graph.length;
    const nodeColors = new Array(numNodes).fill(UNCOLORED);

    // The graph might be disconnected, so we start a fresh coloring from
    // every node that has not been colored yet.
    for (let node = 0; node < numNodes; node++) {
        if (nodeColors[node] !== UNCOLORED) continue;

        // The recursive leap of faith: trust the contract. This call
        // returns true exactly when this whole piece of the graph can
        // be split into two color groups. We do not trace inside; we
        // just return false the moment any piece fails.
        if (!canColorFrom(graph, node, RED, nodeColors)) return false;
    }

    return true;
};

const RED = 1;
const BLUE = -1;
const UNCOLORED = 0;

const buildGraph = (dislikes) => {
    const graph = {};

    for (const dislike of dislikes) {
        const [personOne, personTwo] = dislike;

        const personOneInGraph = graph.hasOwnProperty(personOne);
        const personTwoInGraph = graph.hasOwnProperty(personTwo);

        if (!personOneInGraph) graph[personOne] = [];
        if (!personTwoInGraph) graph[personTwo] = [];

        // Disliking is mutual, so this is an undirected graph.
        graph[personOne].push(personTwo);
        graph[personTwo].push(personOne);
    }

    return graph;
};

// CONTRACT for canColorFrom(graph, person, color, personColors):
//     returns true if `person` can go into the group `color` and
//     everyone connected to `person` through dislikes can be split so
//     that two people who dislike each other never share a group —
//     filling those groups into `personColors` as it goes. Returns
//     false if that is impossible.
//     If `person` already has a group, it returns true exactly when
//     that group is `color` — an earlier call already placed them.
const canColorFrom = (graph, person, color, personColors) => {
    // Base case
    // If this person already has a group color, we just check that it
    // matches the color we wanted to give them. A mismatch means two
    // people who dislike each other were forced into the same group.
    if (personColors[person] !== UNCOLORED) return personColors[person] === color;

    // Process node
    personColors[person] = color;

    // Recurse on neighbors
    // Everyone this person dislikes must go in the other group.
    // Multiplying by -1 flips RED to BLUE and BLUE to RED.
    const oppositeColor = color * -1;

    const personInGraph = graph.hasOwnProperty(person);
    if (!personInGraph) return true;

    const dislikedPeople = graph[person];
    for (const dislikedPerson of dislikedPeople) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns true exactly when the
        // disliked person (and everyone connected to them) can be
        // placed in the opposite group. Trust it, do not trace it.
        // This function already placed `person`, and each disliked
        // person's contract covers the rest — together, that is this
        // function's full contract, kept.
        if (!canColorFrom(graph, dislikedPerson, oppositeColor, personColors)) {
            return false;
        }
    }

    return true;
};

const possibleBipartition = (n, dislikes) => {
    const graph = buildGraph(dislikes);

    // People are numbered 1 through n, so we make the array one slot
    // bigger and simply never use index 0.
    const personColors = new Array(n + 1).fill(UNCOLORED);

    // The dislike graph might be disconnected, so we start a fresh
    // coloring from every person who has not been placed in a group yet.
    for (let person = 1; person <= n; person++) {
        if (personColors[person] !== UNCOLORED) continue;

        // The recursive leap of faith: trust the contract. This call
        // returns true exactly when this whole cluster of people can
        // be split into two groups. We do not trace inside; we just
        // return false the moment any cluster fails.
        if (!canColorFrom(graph, person, RED, personColors)) return false;
    }

    return true;
};

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (board, row, col) => {
    const numRows = board.length;
    const numCols = board[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for canFindWordFrom(board, row, col, word, wordIndex, visited):
//     returns true if the rest of the word — from position `wordIndex`
//     to the end — can be spelled starting at the cell `row`,`col`,
//     stepping only onto side-by-side cells and never reusing a cell
//     already in the visited set. When it returns false, the visited
//     set is back to exactly what it was before the call.
const canFindWordFrom = (board, row, col, word, wordIndex, visited) => {
    // Base cases
    if (!isInBounds(board, row, col)) return false;

    // Each cell can only be used once per word, so cells already on our
    // current path are off limits.
    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return false;

    if (board[row][col] !== word[wordIndex]) return false;

    // We just matched the last letter, so the whole word exists.
    if (wordIndex === word.length - 1) return true;

    // Process node
    visited.add(curPositionString);

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns true exactly when the rest of
        // the word, starting at the next letter, can be spelled from
        // the neighbor cell. Trust it, do not trace it. This cell
        // matched its own letter, and the neighbor's contract covers
        // the remaining letters — together, that is this function's
        // full contract, kept.
        if (canFindWordFrom(board, newRow, newCol, word, wordIndex + 1, visited)) {
            return true;
        }
    }

    // Backtrack: this path failed, so we free up the cell. A different
    // path might still need to walk through it later.
    visited.delete(curPositionString);

    return false;
};

const exist = (board, word) => {
    const numRows = board.length;
    const numCols = board[0].length;

    const visited = new Set();

    // The word could start at any cell, so we try them all.
    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            // The recursive leap of faith: trust the contract. This call
            // returns true exactly when the whole word can be spelled
            // starting at this cell. We do not trace inside; we just
            // return true the moment any starting cell works.
            if (canFindWordFrom(board, row, col, word, 0, visited)) return true;
        }
    }

    return false;
};

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (matrix, row, col) => {
    const numRows = matrix.length;
    const numCols = matrix[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for getLongestPathFrom(matrix, row, col, memo):
//     returns the number of cells in the longest strictly increasing
//     path that starts at the cell `row`,`col`, and saves that answer
//     in `memo` so it never has to be computed again.
const getLongestPathFrom = (matrix, row, col, memo) => {
    // Base case
    // Our real base case is handled automatically: when no neighbor is
    // strictly larger than the current cell, the loop below never recurses
    // and the answer stays at 1 (the cell by itself).
    const curPositionString = getPositionString(row, col);
    if (memo.hasOwnProperty(curPositionString)) return memo[curPositionString];

    // Process node
    // Every cell is an increasing path of length 1 by itself.
    let longestPathFromCur = 1;

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        if (!isInBounds(matrix, newRow, newCol)) continue;

        // We only step onto strictly larger values, so a path can never
        // loop back on itself. That is why we do not need a visited set.
        if (matrix[newRow][newCol] <= matrix[row][col]) continue;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — it returns the length of the longest
        // increasing path starting at the larger neighbor. Trust it,
        // do not trace it. The best path from this cell is this cell
        // plus the best guaranteed path from some larger neighbor —
        // exactly this function's contract, kept.
        const longestPathFromNeighbor = getLongestPathFrom(matrix, newRow, newCol, memo);
        longestPathFromCur = Math.max(longestPathFromCur, 1 + longestPathFromNeighbor);
    }

    memo[curPositionString] = longestPathFromCur;

    return longestPathFromCur;
};

const longestIncreasingPath = (matrix) => {
    const numRows = matrix.length;
    const numCols = matrix[0].length;

    let longestPathLength = 0;
    const memo = {};

    // The best path could start at any cell, so we try them all. The memo
    // makes this fast: each cell is fully solved only once.
    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            // The recursive leap of faith: trust the contract. This call
            // returns the longest increasing path starting at this cell.
            // We do not trace inside; we just keep the biggest answer seen
            // so far.
            const longestPathFromCell = getLongestPathFrom(matrix, row, col, memo);
            longestPathLength = Math.max(longestPathLength, longestPathFromCell);
        }
    }

    return longestPathLength;
};
